void normalizePath() {
	assertThat(PathUtils.normalizePath(null)).isNull();
	assertThat(PathUtils.normalizePath("")).isEmpty();
	assertThat(PathUtils.normalizePath("/")).isEmpty();
	assertThat(PathUtils.normalizePath("admin")).isEqualTo("/admin");
	assertThat(PathUtils.normalizePath("/admin")).isEqualTo("/admin");
	assertThat(PathUtils.normalizePath("/admin/")).isEqualTo("/admin");
	assertThat(PathUtils.normalizePath("/admin/")).isEqualTo("/admin");
	assertThat(PathUtils.normalizePath("//admin/")).isEqualTo("/admin");
}

