	final Resource resource = this.resourceLoader.getResource("classpath:testzipdata/zip-malicious-traversal.zip");
	final InputStream is = resource.getInputStream();

	final Message<InputStream> message = MessageBuilder.withPayload(is).build();

	final UnZipTransformer unZipTransformer = new UnZipTransformer();
	unZipTransformer.afterPropertiesSet();


	assertThatExceptionOfType(MessageTransformationException.class)
			.isThrownBy(() -> unZipTransformer.transform(message))
			.withRootCauseInstanceOf(ZipException.class)
			.withMessageContaining("is trying to leave the target output directory");
}

public void pathParametersAreRemovedFromPathInfo() {
	MockHttpServletRequest request = new MockHttpServletRequest();
	for (Map.Entry<String, String> entry : testPaths.entrySet()) {
		String path = entry.getKey();
		String expectedResult = entry.getValue();
		// Should be null when stripped value is empty
		if (expectedResult.length() == 0) {
			expectedResult = null;
		}
		request.setPathInfo(path);
		RequestWrapper wrapper = new RequestWrapper(request);
		assertThat(wrapper.getPathInfo()).isEqualTo(expectedResult);
		wrapper.reset();
		assertThat(wrapper.getPathInfo()).isEqualTo(path);
	}
}

